// Some portions generated by Claude
import { selectionKeys } from "./graph-selection.ts";

/** A gesture or key and what it does. */
export type GuideItem = { keys: string; text: string };

/** A group of gestures, then any notes that are not about a gesture. */
export type GuideSection = { title: string; items: GuideItem[]; notes?: string[] };

/**
 * How to work the graph, in the platform's own keys: the toolbar's help popover shows it. The canvas describes the same
 * gestures to screen readers in its aria-label; keep the two in step.
 *
 * On Apple platforms a trackpad scrolls with two fingers and zooms with a pinch, and Ctrl-click is the context-menu
 * click; elsewhere the wheel zooms and Ctrl adds to the selection.
 */
export function graphGuide(apple: boolean): GuideSection[] {
  const select = selectionKeys(apple);
  const undo = apple ? "⌘Z" : "Ctrl+Z";
  const redo = apple ? "⇧⌘Z" : "Ctrl+Shift+Z";
  return [
    {
      title: "Mouse and touch",
      items: [
        { keys: "Click a node", text: "Show its details" },
        { keys: "Double-click a node", text: "Load its neighbours" },
        { keys: "Right-click or long-press a node", text: "More actions, such as expanding one relation" },
        { keys: "+N on a node", text: "N more links exist; click to load them" },
        { keys: "Click a link", text: "Show the statement and what its predicate means" },
        { keys: `${select}click`, text: "Add a node to the selection, or take it out" },
        { keys: `${select}drag`, text: "Select the nodes in a box" },
        { keys: "Drag a node", text: "Move it; dragging a selected node moves the whole selection" },
        { keys: "Double-click a node and keep dragging", text: "Move it with the neighbours that link only to it" },
        { keys: apple ? "Drag the background, or scroll" : "Drag the background", text: "Pan" },
        { keys: apple ? "Pinch" : "Scroll", text: "Zoom" },
        { keys: "Double-click the background", text: "Zoom in" },
      ],
    },
    {
      title: "Keyboard",
      items: [
        { keys: "/", text: "Find a node, or search the repository" },
        { keys: "Arrow keys", text: "Go to the nearest node in that direction" },
        { keys: "Enter", text: "Show the node's details" },
        { keys: "Delete", text: "Hide the selection, or the node whose details are shown" },
        { keys: apple ? "⌘A" : "Ctrl+A", text: "Select all drawn nodes" },
        { keys: `${undo}, ${redo}`, text: "Undo or redo a change to the graph" },
        { keys: "Escape", text: "Close the details, then clear the selection" },
      ],
    },
    {
      title: "Good to know",
      items: [],
      notes: [
        "The graph shows only what you load. This browser keeps it for each repository, so it is still here when you come back.",
        "Hiding nodes and clearing the graph only change this view; they never change the repository.",
      ],
    },
  ];
}
